import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_triu_matmul(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ void cute_cp_async_16(
    float* dst, const float* src, bool pred)
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    if (pred) {
        const unsigned smem_addr = __cvta_generic_to_shared(dst);
        asm volatile(
            "cp.async.cg.shared.global [%0], [%1], 16;"
            :
            : "r"(smem_addr), "l"(src));
    }
#else
    if (pred) {
        const float4 v = *reinterpret_cast<const float4*>(src);
        dst[0] = v.x;
        dst[1] = v.y;
        dst[2] = v.z;
        dst[3] = v.w;
    } else {
        dst[0] = 0.0f;
        dst[1] = 0.0f;
        dst[2] = 0.0f;
        dst[3] = 0.0f;
    }
#endif
}
__device__ __forceinline__ void cute_load_stage(
    const float* A,
    const float* B,
    float* smem_stage,
    int N,
    int tid,
    int block_row,
    int block_col,
    int kb)
{
    constexpr int TILE = 32;
    constexpr int SMEM_A_FLOATS = TILE * TILE;
    constexpr int SMEM_A_STRIDE = TILE;
    constexpr int SMEM_B_STRIDE = TILE + 1;
    float* smem_B = smem_stage + SMEM_A_FLOATS;
    float* smem_A = smem_stage;
    for (int linear = tid * 4;
         linear < TILE * TILE;
         linear += blockDim.x * blockDim.y * 4) {
        const int sr = linear / TILE;
        const int sc = linear - sr * TILE;
        const int a_row = block_row + sr;
        const int a_col = kb + sc;
        const int b_row = kb + sr;
        const int b_col = block_col + sc;
        const int a_smem_offset = sr * SMEM_A_STRIDE + sc;
        const int b_smem_offset = sr * SMEM_B_STRIDE + sc;
        const bool a_vec =
            a_row < N &&
            a_col + 3 < N &&
            a_row <= a_col &&
            ((reinterpret_cast<unsigned long long>(
                  A + a_row * N + a_col) & 15ULL) == 0ULL) &&
            ((a_smem_offset & 3) == 0);
        const bool b_vec =
            b_row < N &&
            b_col + 3 < N &&
            b_row <= b_col &&
            ((reinterpret_cast<unsigned long long>(
                  B + b_row * N + b_col) & 15ULL) == 0ULL) &&
            ((b_smem_offset & 3) == 0);
        if (a_vec) {
            cute_cp_async_16(
                smem_A + a_smem_offset,
                A + a_row * N + a_col,
                true);
        } else {
            for (int q = 0; q < 4; ++q) {
                const int col = a_col + q;
                smem_A[a_smem_offset + q] =
                    (a_row < N && col < N && a_row <= col)
                        ? A[a_row * N + col]
                        : 0.0f;
            }
        }
        if (b_vec) {
            cute_cp_async_16(
                smem_B + b_smem_offset,
                B + b_row * N + b_col,
                true);
        } else {
            for (int q = 0; q < 4; ++q) {
                const int col = b_col + q;
                smem_B[b_smem_offset + q] =
                    (b_row < N && col < N && b_row <= col)
                        ? B[b_row * N + col]
                        : 0.0f;
            }
        }
    }
}
__global__ void cute_triu_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N)
{
    constexpr int TILE = 32;
    constexpr int THREAD_TILE = 16;
    constexpr int SMEM_A_FLOATS = TILE * TILE;
    constexpr int SMEM_B_STRIDE = TILE + 1;
    constexpr int SMEM_B_FLOATS = TILE * SMEM_B_STRIDE;
    constexpr int SMEM_STAGE_FLOATS = SMEM_A_FLOATS + SMEM_B_FLOATS;
    extern __shared__ float smem[];
    float* stage0 = smem;
    float* stage1 = smem + SMEM_STAGE_FLOATS;
    const int tid = threadIdx.y * blockDim.x + threadIdx.x;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int block_row = static_cast<int>(blockIdx.y) * TILE;
    const int block_col = static_cast<int>(blockIdx.x) * TILE;
    float acc0 = 0.0f;
    float acc1 = 0.0f;
    float acc2 = 0.0f;
    float acc3 = 0.0f;
    const bool active_tile = blockIdx.y <= blockIdx.x;
    if (active_tile) {
        const int k_begin = block_row;
        const int k_end = min(N, block_col + TILE);
        int kb = k_begin;
        int current_stage = 0;
        if (kb < k_end) {
            cute_load_stage(A, B, stage0, N, tid, block_row, block_col, kb);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
            asm volatile("cp.async.commit_group;");
            asm volatile("cp.async.wait_group 0;");
#endif
            __syncthreads();
        }
        for (; kb < k_end; kb += TILE) {
            const int next_kb = kb + TILE;
            const int next_stage = current_stage ^ 1;
            if (next_kb < k_end) {
                cute_load_stage(
                    A, B,
                    next_stage == 0 ? stage0 : stage1,
                    N, tid, block_row, block_col, next_kb);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
                asm volatile("cp.async.commit_group;");
#endif
            }
            float* smem_stage =
                current_stage == 0 ? stage0 : stage1;
            float* smem_A = smem_stage;
            float* smem_B = smem_stage + SMEM_A_FLOATS;
#pragma unroll
            for (int k = 0; k < TILE; ++k) {
                const float b = smem_B[k * SMEM_B_STRIDE + tx];
                const float a0 = smem_A[(ty + 0 * 8) * TILE + k];
                const float a1 = smem_A[(ty + 1 * 8) * TILE + k];
                const float a2 = smem_A[(ty + 2 * 8) * TILE + k];
                const float a3 = smem_A[(ty + 3 * 8) * TILE + k];
                acc0 += a0 * b;
                acc1 += a1 * b;
                acc2 += a2 * b;
                acc3 += a3 * b;
            }
            if (next_kb < k_end) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
                asm volatile("cp.async.wait_group 0;");
#endif
                __syncthreads();
                current_stage = next_stage;
            }
        }
    }
    const int col = block_col + tx;
    const int row0 = block_row + ty + 0 * 8;
    const int row1 = block_row + ty + 1 * 8;
    const int row2 = block_row + ty + 2 * 8;
    const int row3 = block_row + ty + 3 * 8;
    if (row0 < N && col < N) {
        C[row0 * N + col] = (row0 <= col) ? acc0 : 0.0f;
    }
    if (row1 < N && col < N) {
        C[row1 * N + col] = (row1 <= col) ? acc1 : 0.0f;
    }
    if (row2 < N && col < N) {
        C[row2 * N + col] = (row2 <= col) ? acc2 : 0.0f;
    }
    if (row3 < N && col < N) {
        C[row3 * N + col] = (row3 <= col) ? acc3 : 0.0f;
    }
}


torch::Tensor cute_triu_matmul(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "A and B must be float32 tensors");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(0) == B.size(0), "A and B must have the same shape");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();

    const int N = static_cast<int>(A_c.size(0));
    auto C = torch::empty_like(A_c);

    constexpr int TILE = 32;
    dim3 block(32, 8);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);

    const size_t shared_bytes =
        2 * (TILE * TILE + TILE * (TILE + 1)) * sizeof(float);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_triu_matmul_kernel<<<grid, block, shared_bytes, stream>>>(
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>(),
        N);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE triangular matrix multiplication kernel launch failed");

    return C;
}
"""


cute_ext = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_triu_matmul(A, B)

